'use strict';
const E=NarutoEditor,$=s=>document.querySelector(s),panel=$('#panel');
let model=null,sha='',stage=1,sub=0,tab='actors',page=0,search='',dialoguePart='all',activeText=null,selectedActor=0,selectedObject=0,toastTimer;
const state={get model(){return model;},get sha(){return sha;}};window.editorState=state;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const special={0:'空位',255:'当前队伍 · 位置 1',254:'当前队伍 · 位置 2',253:'当前队伍 · 位置 3',252:'卡片人物 · 位置 1',251:'卡片人物 · 位置 2',250:'卡片人物 · 位置 3'};
const actorName=id=>special[id]||model?.campaignData?.()?.chapters.find(c=>c.id===stage)?.aliases?.[id]||model?.characterName(id)||E.names[id]||`未命名角色（编号 ${id}）`;
const opts=(items,value)=>items.map(([v,t])=>`<option value="${v}" ${+value===+v?'selected':''}>${esc(t)}</option>`).join('');
const charOptions=id=>opts([[0,'空位']],id)+`<optgroup label="固定出场人物">${opts(model.characters.map(c=>[c.id,actorName(c.id)]),id)}</optgroup><optgroup label="跟随战前编队">${opts([255,254,253].map(k=>[k,special[k]]),id)}</optgroup><optgroup label="卡片人物位置">${opts([252,251,250].map(k=>[k,special[k]]),id)}</optgroup>`;
const sides=id=>opts([[0,'我方'],[1,'敌方']],id);
function actorEntryRule(id,side){if(!id)return '空位';if(id>=253)return '读取战前编队位置';if(id>=250)return '读取卡片人物位置';if(!side&&id<=21)return '固定人物 · 按开局替代映射';return '固定人物';}
const number=(name,value,min=0,max=63)=>`<input type="number" name="${name}" value="${value}" min="${min}" max="${max}" aria-label="${name}">`;
function notify(message,error=false){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').style.background=error?'#97472e':'#274c38';$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,6000);}
function run(fn){try{return fn();}catch(e){notify(e.message,true);console.error(e);}}
async function sha256(bytes){return [...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');}
function updateStatus(){if(!model)return;let n=model.edits.size,t=model.textEdits.size;const extra=model.exportFeatures();$('#changeCount').textContent=`${n} 个数据字节 · ${t} 段文字 · ${Object.keys(extra.maps).length} 张地图 · ${Object.values(extra.events).flat().length} 条自定义事件 · ${Object.keys(extra.assets?.portraits||{}).length+Object.keys(extra.assets?.sprites||{}).length+Object.keys(extra.assets?.maps||{}).length+(extra.assets?.palettes||[]).length} 份素材`;$('#undo').disabled=!model.history.length;$('#status').textContent=`已打开 ${model.label}　｜　第 ${stage} ${model.battleIds().includes(stage)?'战场':'剧情'}${model.battleIds().includes(stage)?` · 配置 ${sub+1}`:''}　｜　修改在导出后生效`;}
async function openBytes(bytes,label){const m=new E.Editor(bytes,label);const digest=await sha256(m.rom);model=m;sha=digest;window.dispatchEvent(new CustomEvent('romloaded'));$('#filename').textContent=label;$('#identity').textContent=`${(m.rom.length/1048576).toFixed(2)} MB · AUEJ\nSHA-256 ${digest}`;for(const id of ['exportRom','exportIps','saveProject','stage','sub','projectFile','addCampaignBattle'])$('#'+id).disabled=false;$('#stage').innerHTML=model.sceneIds().map(i=>`<option value="${i}">${model.battleIds().includes(i)?'战场':'剧情'} ${String(i).padStart(2,'0')}</option>`).join('');$('#empty').hidden=true;panel.hidden=false;stage=1;sub=0;initializeFlow();render();updateStatus();}
window.openRomBytes=openBytes;
$('#romFile').onchange=async e=>{const f=e.target.files[0];if(f){try{await openBytes(new Uint8Array(await f.arrayBuffer()),f.name);notify('已载入，可开始编辑');}catch(err){notify(err.message,true);}}e.target.value='';};
$('#stage').onchange=e=>{stage=+e.target.value;currentFlow=null;page=0;search='';render();updateStatus();};$('#sub').onchange=e=>{sub=+e.target.value;render();updateStatus();};
$('#tabs').onclick=e=>{const b=e.target.closest('button');if(!b)return;tab=b.dataset.tab;page=0;render();};
function render(){if(tab!=='dialogue'&&typeof stopBgmPreview==='function')stopBgmPreview();if(model)renderFlowHeading();syncGlyphTab();document.querySelectorAll('#tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));if(!model)return;$('#sub').disabled=!model.battleIds().includes(stage);
 if(!model.battleIds().includes(stage)&&!['dialogue','changes','glyphs','assets'].includes(tab)){panel.innerHTML='<div class="card"><h2>这个编号仅有剧情</h2><p>请切换到“剧情对话”，出场人物和胜负条件仅适用于战场 01～46。</p></div>';return;}
 ({actors:renderActors,rules:renderRules,dialogue:renderDialogue,objects:renderObjects,map:renderMapEditor,events:renderEvents,changes:renderChanges,glyphs:renderGlyphAudit,assets:renderAssetImports}[tab])();}
function transaction(label,fn,redraw=true){model.transaction(label,fn);updateStatus();if(redraw)render();notify(`已保存：${label}`);}
function renderActors(){const actors=model.actors(stage,sub);panel.innerHTML=`<div class="sectionhead"><div><h2>出场人物</h2><p>选择人物与阵营，修改等级和初始坐标。</p></div><span class="badge">${actors.filter(a=>a.id).length} / 12 个位置</span></div><div class="split"><div class="card tablewrap"><table><thead><tr><th>位置</th><th>人物</th><th>出场规则</th><th>阵营</th><th>等级</th><th>X</th><th>Y</th><th>朝向</th><th>不可战胜</th></tr></thead><tbody>${actors.map(a=>`<tr class="actorrow" data-index="${a.index}" data-empty="${!a.id}"><td>${a.index+1}</td><td><div class="actorchoice"><canvas class="portrait" data-portrait="${a.id}" width="80" height="80"></canvas><select name="id">${charOptions(a.id)}</select></div></td><td class="entryrule">${actorEntryRule(a.id,a.side)}</td><td><select name="side">${sides(a.side)}</select></td><td>${number('level',a.level,0,99)}</td><td>${number('x',a.x)}</td><td>${number('y',a.y)}</td><td><select name="facing">${opts(E.directions,a.facing)}</select></td><td><input type="checkbox" name="invulnerable" aria-label="本场不可战胜" title="仅本场生效，不写入人物存档" ${a.invulnerable?'checked':''} ${model.campaign?.capabilities?.invulnerablePositions&&a.side?'':'disabled'}></td></tr>`).join('')}</tbody></table><p class="hint">选具体姓名＝固定出场，战前换队员不改变此位置；选“当前队伍 · 位置 1／2／3”＝跟随战前编队，位置为空则不出场。我方已有的人物读取存档等级与装备；未加入者使用关卡预设。原三人及被交换的人物仍按开局替代映射。</p></div><div class="card mapcard"><h2>实际地图与出场位置</h2><canvas id="grid" width="480" height="240"></canvas><div class="gridlegend"><span><i style="background:#39825b"></i>我方</span><span><i style="background:#cb7758"></i>敌方</span></div><p class="gridnote">先点人物行，再点底图调整坐标。地形编辑请使用“关卡地图”。</p><p id="selection" class="hint"></p></div></div><div class="notice">坐标必须落在游戏实际地图可站立的位置。更换敌方人物时，编辑器同步采用该人物的基础忍术配置；复杂变身、召唤与关卡 AI 尚未逐项验证。</div>`;
 panel.querySelectorAll('.actorrow').forEach(row=>{row.onclick=()=>{selectedActor=+row.dataset.index;drawGrid();};row.onchange=()=>run(()=>{const v={};row.querySelectorAll('[name]').forEach(e=>v[e.name]=e.type==='checkbox'?e.checked:+e.value);transaction(`人物位置 ${+row.dataset.index+1}`,()=>model.setActor(stage,sub,+row.dataset.index,v),false);row.dataset.empty=!v.id;row.querySelector('.entryrule').textContent=actorEntryRule(v.id,v.side);const guard=row.querySelector('[name=invulnerable]');guard.checked=model.actors(stage,sub)[+row.dataset.index].invulnerable;guard.disabled=!model.campaign?.capabilities?.invulnerablePositions||!v.side;drawPortrait(row.querySelector('.portrait'),v.id);drawGrid();});});paintPortraits(panel);drawGrid();}
function drawGrid(){const canvas=$('#grid');if(!canvas)return;const actors=model.actors(stage,sub),m=model.mapData(stage);drawBattleCanvas(canvas,stage,{actors,selected:selectedActor,objects:model.objects(stage,sub)});
 $('#selection').textContent=`选中位置 ${selectedActor+1}：${actorName(actors[selectedActor].id)}`;
 canvas.onclick=e=>run(()=>{const {x,y}=battleCell(canvas,e,m),a=actors[selectedActor];if(!a.id)throw Error('请先为这个位置选择人物');transaction('调整人物坐标',()=>model.setActor(stage,sub,a.index,{...a,x,y}));});}
const ruleTypes=[[0,'停用'],[1,'一方全部人物被击败'],[2,'到达回合上限'],[3,'指定人物退场'],[4,'到达回合上限（原类型 4）'],[5,'战场计数达到指定值'],[6,'指定物品已消失（拾取等）'],[7,'限时后比较双方体力'],[8,'限时后比较双方人数'],[9,'限时后比较双方积分']];
function renderRules(){const r=model.rules(stage,sub);panel.innerHTML=`<div class="sectionhead"><div><h2>胜利与失败</h2><p>修改实际判定，并为玩家编写一致的条件说明。</p></div><label>回合上限（0 不限；255 继承）${number('turn',r.turn,0,255)}</label></div><div class="card"><h2>任务文字</h2><div class="toolbar">${model.missionTexts(stage,sub).map((e,i)=>`<button data-mission="${i}">编辑${e.label}</button>`).join('')}</div><p class="hint">这里的说明不会自动修改战斗判定，请与下方实际条件保持一致。</p></div><div class="notice">每组满足任意一条即可触发，多条条件的顺序影响优先级。原剧情还可能检查人物、回合或物品事件；改变条件后需在游戏内验证后续剧情。</div><div class="rulegroups">${r.groups.map((rules,g)=>`<div class="card"><h2>${g?'失败条件':'胜利条件'}</h2>${rules.map(rule=>`<div class="rule" data-group="${g}" data-index="${rule.index}"><div class="row"><label>条件 ${rule.index+1}<select name="type">${opts(ruleTypes.concat(model.campaign?.capabilities?.arrivalRules?[[10,'指定我方人物到达撤离点']]:[]),rule.type)}</select></label></div><div class="rulefields">${ruleFields(rule)}</div><canvas width="560" height="48" data-rule="${g}-${rule.index}"></canvas><div class="rulefooter"><button class="small edit-rule-text" ${rule.pointer<0?'disabled':''}>编辑说明</button><select class="copyfrom">${opts(rules.filter(x=>x.type&&x.index!==rule.index).map(x=>[x.index,`复制条件 ${x.index+1}`]),-1)}</select><button class="small copy-rule">复制</button></div></div>`).join('')}</div>`).join('')}</div>`;
 panel.querySelectorAll('[data-object-go]').forEach(b=>b.onclick=()=>{selectedObject=+b.dataset.objectGo;tab='objects';render();});
 panel.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>openText(model.missionTexts(stage,sub)[+b.dataset.mission],'编辑任务文字'));
 panel.querySelector('[name=turn]').onchange=e=>run(()=>transaction('回合上限',()=>model.setTurn(stage,sub,+e.target.value)));
 panel.querySelectorAll('.rule').forEach(el=>{let g=+el.dataset.group,i=+el.dataset.index,rule=r.groups[g][i];el.querySelectorAll('[name]').forEach(field=>field.onchange=()=>run(()=>{const v={type:rule.type,a:rule.a,b:rule.b,c:rule.c};el.querySelectorAll('[name]').forEach(e=>v[e.name]=+e.value);transaction(`${g?'失败':'胜利'}条件 ${i+1}`,()=>model.setRule(stage,sub,g,i,v));}));const text=model.ruleText(rule);if(text)paintText(el.querySelector('canvas'),model.textValue(text),2);el.querySelector('.edit-rule-text').onclick=()=>openText(text,'条件说明');el.querySelector('.copy-rule').onclick=()=>run(()=>{let from=+el.querySelector('.copyfrom').value;if(!el.querySelector('.copyfrom').options.length)throw Error('本组没有可复制的条件');transaction('复制条件',()=>model.copyRule(stage,sub,g,i,from));});});}
function ruleFields(r){if(!r.type)return '<p class="hint">保留原位置，可复制已有条件后启用。</p>';if(r.type===10)return `<label>撤离人物<select name="a">${opts(model.characters.map(c=>[c.id,actorName(c.id)]),r.a)}</select></label><label>撤离点 X${number('b',r.b,0,model.mapData(stage).width-1)}</label><label>撤离点 Y${number('c',r.c,0,model.mapData(stage).height-1)}</label><p class="hint">该我方人物到达此格并结束行动才满足条件。改坐标后，请同步调整地图上的撤离图案。</p>`;if([2,4].includes(r.type))return '<p class="hint">使用本配置的回合上限。</p>';if(r.type===6){const candidates=model.objectSlot(stage,sub,r.a);return `<div class="objectcondition"><label>战斗中生成的物品<select name="a">${opts(Array.from({length:16},(_,i)=>{const list=model.objectSlot(stage,sub,i);return [i,`第 ${i+1} 个 · ${list.length?list.map(o=>`记录 ${o.index+1} ${o.name}`).join(' / '):'开场无预设物品'}`];}),r.a)}</select></label><p class="hint">这是生成顺序，不是地图坐标。空记录不占号；已领取的卡片、不满足出现条件的卷轴会被跳过，后面编号可能提前。${candidates.length>1?'当前编号有多个可能对应，需结合存档确认。':!candidates.length?'开场空编号可能使条件立即成立。':''}</p><button type="button" class="small" data-object-go="${candidates[0]?.index??-1}" ${!candidates.length?'disabled':''}>查看对应物品和地图</button></div>`;}let s=`<label>判定哪一方<select name="a">${sides(r.a)}</select></label>`;if(r.type===3)s+=`<label>指定人物<select name="b">${opts(model.characters.map(c=>[c.id,actorName(c.id)]),r.b)}</select></label>`;if(r.type===5)s+=`<label>计数阈值${number('b',r.b,0,255)}</label>`;return s;}
function renderObjects(){const a=model.objects(stage,sub),m=model.mapData(stage),spawns=model.objectSpawns(stage,sub);panel.innerHTML=`<div class="sectionhead"><div><h2>战场物品</h2><p>先选类别与具体物品，再点右侧地图放置。物品使用金色“物”标记。</p></div><span class="badge">${spawns.length} / 16 条记录</span></div><div class="objectlayout"><div class="card tablewrap"><table><thead><tr><th>记录</th><th>类别</th><th>具体物品 / 所属人物</th><th>X</th><th>Y</th></tr></thead><tbody>${a.map(o=>{const choices=model.objectChoices(o.type);if(o.type&&!choices.some(([id])=>id===o.target))choices.unshift([o.target,`未识别内容（原编号 ${o.target}）`]);return `<tr class="objectrow" data-index="${o.index}" data-empty="${!o.type}"><td><button class="small selectObject" aria-label="选择物品记录 ${o.index+1}">${o.index+1}</button></td><td><select name="type" aria-label="物品类别">${opts(E.objectTypes,o.type)}</select></td><td><select name="target" aria-label="具体物品" ${!o.type?'disabled':''}>${opts(choices.length?choices:[[0,'先选择类别']],o.target)}</select></td><td>${number('x',o.x,0,m.width-1)}</td><td>${number('y',o.y,0,m.height-1)}</td></tr>`;}).join('')}</tbody></table></div><div class="card objectmap"><h2>物品位置</h2><p id="objectSelection"></p><div class="objectmapscroll"><canvas id="objectMap" aria-label="点击地图放置所选物品"></canvas></div><p id="objectHint" class="hint"></p><div id="objectLocations"></div><p class="hint">左上角是 (0, 0)，X 向右，Y 向下。金色“物1”对应左表记录 1；绿色和红色数字是人物位置。</p></div></div><div class="notice">记录 1～16 用来存放地图配置。“指定物品已消失”的条件检查战斗中生成的编号：空记录会跳过，已领取的卡片和不满足条件的卷轴也可能不出现，所以不能始终把记录行号当作条件编号。机关宝箱和剧情物件调用原关卡脚本，移到别关时须检查其效果。</div>`;
 panel.querySelectorAll('.objectrow').forEach(row=>{row.onclick=()=>{selectedObject=+row.dataset.index;drawObjectMap();};row.onchange=e=>run(()=>{selectedObject=+row.dataset.index;const v={};row.querySelectorAll('[name]').forEach(el=>v[el.name]=+el.value);if(e.target.name==='type'){const choices=model.objectChoices(v.type);if(!choices.some(([id])=>id===v.target))v.target=choices[0]?.[0]||0;}if(v.type&&(v.x>=m.width||v.y>=m.height))throw Error('物品坐标超出实际地图');transaction(`物品记录 ${selectedObject+1}`,()=>model.setObject(stage,sub,selectedObject,v));});});
 $('#objectMap').onclick=e=>run(()=>{const o=model.objects(stage,sub)[selectedObject];if(!o.type)throw Error('请先在左表为这条记录选择类别和具体物品');const {x,y}=battleCell(e.currentTarget,e,m),other=model.objects(stage,sub).find(a=>a.type&&a.index!==o.index&&a.x===x&&a.y===y);if(other)throw Error(`这一格已有物品记录 ${other.index+1}，请换一个空格`);transaction('在地图上放置物品',()=>model.setObject(stage,sub,o.index,{...o,x,y}));});drawObjectMap();}
function drawObjectMap(){const canvas=$('#objectMap');if(!canvas)return;const a=model.objects(stage,sub),o=a[selectedObject],spawns=model.objectSpawns(stage,sub),spawn=spawns.find(x=>x.index===o.index);panel.querySelectorAll('.objectrow').forEach(row=>row.classList.toggle('selected',+row.dataset.index===selectedObject));drawBattleCanvas(canvas,stage,{actors:model.actors(stage,sub),objects:a,selectedObject});$('#objectSelection').textContent=`选中记录 ${selectedObject+1}：${model.objectName(o)}${o.type?` · (${o.x}, ${o.y})`:''}`;$('#objectHint').textContent=model.objectHint(o)+(spawn?` 开场生成编号${spawn.spawnMin===spawn.spawnMax?'':'可能'}为 ${spawn.spawnMin}${spawn.spawnMax!==spawn.spawnMin?'～'+spawn.spawnMax:''}${spawn.conditional?'；此物品可能不生成':''}。`:'');$('#objectLocations').innerHTML=spawns.length?`<details><summary>地图上的 ${spawns.length} 个物品</summary>${spawns.map(x=>`<button class="objectLocation small" data-index="${x.index}">物${x.index+1} · ${esc(x.name)} (${x.x}, ${x.y})</button>`).join('')}</details>`:'<p class="hint">本配置还没有物品；可从左表空记录开始添加。</p>';panel.querySelectorAll('.objectLocation').forEach(b=>b.onclick=()=>{selectedObject=+b.dataset.index;drawObjectMap();});}
function renderDialogue(){const selection=currentFlow?.kind==='story'?currentFlow:null,all=model.dialogueSequence(stage,selection||{}),entries=all.filter(e=>(selection||dialoguePart==='all'||model.dialogueParts(stage,e).includes(dialoguePart))&&(!search||model.textValue(e).includes(search)||E.hex(e.offset).includes(search.toUpperCase())||e.text.tokens.some(t=>t.code>=0x8000&&E.hex(t.code,4)===search.toUpperCase()))),count=Math.max(1,Math.ceil(entries.length/25));page=Math.min(page,count-1);panel.innerHTML=`<div class="sectionhead"><div><h2>${selection?esc(selection.title):'剧情对话'}</h2><p>内部剧情 ${stage} · 当前显示 ${entries.length} 段 · 依据脚本执行关系排列</p></div><span class="badge">普通对话可编辑</span></div><div id="storyBackground" class="card"></div><div class="searchrow"><select id="dialoguePart"><option value="all">全部剧情分支</option><option value="before">开场 / 战前过场</option><option value="after">通关后 / 关卡衔接</option><option value="battle">原有战中事件</option></select><input id="textSearch" type="search" placeholder="搜索中文、字码或片段位置" value="${esc(search)}"><button id="searchButton">搜索</button></div><p class="hint">上方为可复制的中文对照，下方为 ROM 原字形。中文由字序与上下文推断，尚未逐字人工确认；不确定字保留字码。你提供的 62 条校对已保存；需要修正时可从左侧“文字工具”打开字形校对。选项分支不代表全部会在一次游戏中依次发生。</p><div class="dialoglist">${entries.slice(page*25,page*25+25).map((e,i)=>`<div class="dialogrow"><div class="dialogmeta"><canvas class="portrait" data-portrait="${e.speaker}" width="80" height="80"></canvas><span>${esc(e.speaker?actorName(e.speaker):'旁白')}<br>${E.hex(e.offset)}<br>${e.op===1?'对话':e.op===5?'选项':'特殊窗口'}${model.textEdits.has(e.key)?' · 已改':''}</span></div><div class="dialogcontent"><p class="readable">${esc(readableText(model.textValue(e)))}</p><canvas width="840" height="64" data-entry="${i}"></canvas></div><button class="small" data-entry="${i}">${e.op===1&&e.length>=5&&!e.customEvent?'编辑':'查看'}</button></div>`).join('')}</div><div class="pager"><button id="prev" ${!page?'disabled':''}>上一页</button><span>第 ${page+1} / ${count} 页</span><button id="next" ${page>=count-1?'disabled':''}>下一页</button></div>`;$('#dialoguePart').value=selection?selection.part:dialoguePart;$('#dialoguePart').onchange=e=>{currentFlow=null;dialoguePart=e.target.value;page=0;renderFlowHeading();renderDialogue();};showStoryBackground($('#storyBackground'),selection?.root);const shown=entries.slice(page*25,page*25+25);panel.querySelectorAll('.dialogcontent canvas').forEach(c=>paintText(c,nativePreviewValue(shown[+c.dataset.entry]),2));paintPortraits(panel);panel.querySelectorAll('.dialogrow button').forEach(b=>b.onclick=()=>openText(shown[+b.dataset.entry]));$('#prev').onclick=()=>{page--;renderDialogue();};$('#next').onclick=()=>{page++;renderDialogue();};const find=()=>{search=$('#textSearch').value;page=0;renderDialogue();};$('#searchButton').onclick=find;$('#textSearch').onkeydown=e=>{if(e.key==='Enter')find();};}
function renderChanges(){const edits=[...model.edits].sort((a,b)=>a[0]-b[0]);panel.innerHTML=`<div class="sectionhead"><div><h2>修改记录</h2><p>数据变化与台词改写均在导出时写入新文件。</p></div><span class="badge">${edits.length} 字节 · ${model.textEdits.size} 段文字</span></div><div class="card tablewrap"><table class="changetable"><thead><tr><th>类别 / 位置</th><th>修改前</th><th>修改后</th></tr></thead><tbody>${edits.slice(0,300).map(([p,v])=>`<tr><td>数据 ${E.hex(p)}</td><td>${E.hex(model.rom[p],2)}</td><td>${E.hex(v,2)}</td></tr>`).join('')}${[...model.textEdits.values()].map(e=>`<tr><td>${e.kind==='script'?'对话':'说明'} ${E.hex(e.offset)}</td><td>原游戏文字</td><td>${esc(e.value.slice(0,150))}${e.speaker?`<br>说话人：${actorName(e.speaker)}`:''}</td></tr>`).join('')}</tbody></table>${edits.length>300?'<p class="hint">仅列前 300 个字节；工程文件保留全部修改。</p>':''}${!edits.length&&!model.textEdits.size?'<p class="hint">还没有修改。</p>':''}</div>`;}
const glyphCache=new Map();
function newGlyph(ch){if(glyphCache.has(ch))return glyphCache.get(ch);const c=document.createElement('canvas');c.width=16;c.height=16;let ctx=c.getContext('2d',{willReadFrequently:true});ctx.clearRect(0,0,16,16);ctx.font='16px SimSun,"Noto Serif CJK SC",serif';ctx.textBaseline='alphabetic';ctx.fillStyle='black';ctx.fillText(ch,0,14);const rgba=ctx.getImageData(0,0,16,16).data,pixels=new Uint8Array(128),g=new Uint8Array(32);for(let y=0;y<16;y++)for(let x=0;x<8;x++){let a=rgba[(y*16+x*2)*4+3],b=rgba[(y*16+x*2+1)*4+3];if(Math.max(a,b)>100)pixels[y*8+x]=3;}for(let y=15;y>=0;y--)for(let x=7;x>=0;x--){if(pixels[y*8+x]===3){if(x<7&&!pixels[y*8+x+1])pixels[y*8+x+1]=1;if(y<15&&!pixels[(y+1)*8+x])pixels[(y+1)*8+x]=1;}}for(let j=0;j<32;j++)for(let k=0;k<4;k++)g[j]|=pixels[Math.floor(j/2)*8+(j%2)*4+k]<<(k*2);glyphCache.set(ch,g);return g;}
window.renderNewGlyph=newGlyph;
function paintText(canvas,value,scale=3){if(!canvas||!model)return;const ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);ctx.fillStyle='#eaf0dc';ctx.fillRect(0,0,canvas.width,canvas.height);let x=8,y=6;const tokens=run(()=>model.tokenize(value.replaceAll('【分页】','\n\n')));if(!tokens)return;const reverse={};for(const[k,v]of Object.entries(model.mapping))reverse[v]=+k;for(const t of tokens){let code=t.raw?.length===2&&!([1,2].includes(t.raw[0]))?t.raw[0]*256+t.raw[1]:t.raw?.[0];if(code===10){x=8;y+=18*scale;continue;}if(t.raw&&code<32)continue;let g=t.char?(E.glyph(model.rom,reverse[t.char])||newGlyph(t.char)):E.glyph(model.rom,code);if(x+8*scale>canvas.width){x=8;y+=18*scale;}if(y+16*scale>canvas.height)break;if(g){for(let j=0;j<32;j++)for(let k=0;k<4;k++){const v=(g[j]>>(k*2))&3;if(v){ctx.fillStyle=v===3?'#263c2c':v===1?'#899575':'#c7cfad';ctx.fillRect(x+((j%2)*4+k)*scale,y+Math.floor(j/2)*scale,scale,scale);}}}else{ctx.fillStyle='#263c2c';ctx.font=`${14*scale}px monospace`;ctx.fillText(String.fromCharCode(code||32),x,y+14*scale);}x+=8*scale;}}
window.paintNativeText=paintText;
function openText(entry,title='编辑剧情对话'){if(!entry)return;activeText=entry;const readOnly=entry.kind==='script'&&(entry.op!==1||entry.length<5||entry.customEvent);$('#textTitle').textContent=title;$('#textMeta').textContent=`${entry.kind==='script'?'剧情片段':'条件说明'} ${E.hex(entry.offset)}${entry.customEvent?' · 请到条件剧情页面修改':readOnly?' · 当前只读':''}`;$('#textInput').value=model.textValue(entry);$('#textInput').readOnly=readOnly;$('#speaker').innerHTML=opts([[0,`沿用原来的姓名与头像${entry.speaker?' · '+actorName(entry.speaker):''}`],...model.characters.map(c=>[c.id,actorName(c.id)])],model.speaker(entry));$('#speakerRow').hidden=entry.kind!=='script';$('#speaker').disabled=readOnly;$('#saveText').disabled=readOnly;$('#paginate').disabled=readOnly||entry.kind!=='script';$('#pageBreak').disabled=readOnly||entry.kind!=='script';$('#glyphToggle').disabled=readOnly;$('#glyphPicker').hidden=true;showStoryBackground($('#modalBackground'));drawPortrait($('#speakerPortrait'),model.speaker(entry)||entry.speaker||0);updateTextPreview();$('#textModal').showModal();}
function updateTextPreview(){if(!activeText)return;const value=$('#textInput').value;let tokens;try{tokens=model.tokenize(value.replaceAll('【分页】','\n'));}catch(e){$('#textWarning').textContent=e.message;return;}let lines=1,width=0,max=0;tokens.forEach(t=>{if(t.raw?.[0]===10){lines++;max=Math.max(max,width);width=0;}else if(!t.raw||t.raw[0]>=32)width++;});max=Math.max(max,width);const pages=value.split('【分页】').length;$('#textStats').textContent=`${tokens.filter(t=>!t.raw||t.raw[0]>=32).length} 个显示字形 · ${lines} 行 · ${pages} 页 · 最长行 ${max} 字`;$('#textWarning').textContent=max>28?'有较长行，请换行或分页后在游戏内确认。':lines>pages*2?'单页行数较多，请检查分页。':'中文新字会随导出写入剩余字库。';paintText($('#textPreview'),value===model.textValue(activeText)?nativePreviewValue(activeText):value,3);}
$('#textInput').oninput=updateTextPreview;$('#speaker').onchange=()=>{drawPortrait($('#speakerPortrait'),+$('#speaker').value||activeText?.speaker||0);updateTextPreview();};$('#closeText').onclick=()=>$('#textModal').close();
function insertText(s){const e=$('#textInput');e.setRangeText(s,e.selectionStart,e.selectionEnd,'end');e.focus();updateTextPreview();}
$('#pageBreak').onclick=()=>insertText('【分页】');$('#paginate').onclick=()=>run(()=>{const text=$('#textInput').value;if(text.includes('{#'))throw Error('包含游戏控制码，请保留控制码并手动分页。');const ts=model.tokenize(text.replaceAll('【分页】','')),lines=[];let line='',n=0;for(const t of ts){if(t.raw?.[0]===10){lines.push(line);line='';n=0;continue;}if(n>=24){lines.push(line);line='';n=0;}line+=t.char||String.fromCharCode(...t.raw.map(v=>v));if(t.raw?.length===2)line=line.slice(0,-2)+`{字${E.hex(t.raw[0]*256+t.raw[1],4)}}`;n++;}if(line)lines.push(line);const pages=[];for(let i=0;i<lines.length;i+=2)pages.push(lines.slice(i,i+2).join('\n'));$('#textInput').value=pages.join('【分页】');updateTextPreview();});
$('#saveText').onclick=()=>run(()=>{model.tokenize($('#textInput').value.replaceAll('【分页】',''));transaction('修改文字与说话人',()=>model.setText(activeText,$('#textInput').value,activeText.kind==='script'?+$('#speaker').value:0));$('#textModal').close();});
$('#glyphToggle').onclick=()=>{let picker=$('#glyphPicker');picker.hidden=!picker.hidden;if(!picker.hidden){$('#glyphPage').innerHTML=E.fontSegments(model.rom).filter(s=>s.count).map(s=>`<option value="${s.index}">${E.hex(s.start,4)} 起 · ${s.count} 字</option>`).join('');renderGlyphPage();}};
function renderGlyphPage(){const s=E.fontSegments(model.rom)[+$('#glyphPage').value],grid=$('#glyphGrid');grid.replaceChildren();for(let i=0;i<s.count;i++){let code=s.start+i,b=document.createElement('button'),c=document.createElement('canvas');c.width=8;c.height=16;b.type='button';b.title=`字形 ${E.hex(code,4)} · ${model.mapping[code]||'待识别'}`;b.append(c);const label=document.createElement('span');label.textContent=model.mapping[code]||'?';b.append(label);paintText(c,`{字${E.hex(code,4)}}`,1); // miniature is drawn below without margins
 const ctx=c.getContext('2d'),g=E.glyph(model.rom,code);ctx.clearRect(0,0,8,16);ctx.fillStyle='#294433';for(let j=0;j<32;j++)for(let k=0;k<4;k++)if(((g[j]>>(k*2))&3)===3)ctx.fillRect((j%2)*4+k,Math.floor(j/2),1,1);b.onclick=()=>insertText(`{字${E.hex(code,4)}}`);grid.append(b);}}
$('#glyphPage').onchange=renderGlyphPage;
function download(bytes,name,type='application/octet-stream'){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([bytes],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function exportBytes(){if(!model)throw Error('请先打开 ROM');return model.build(newGlyph);}
window.buildEditorRom=exportBytes;
$('#exportRom').onclick=()=>run(()=>{const bytes=exportBytes();download(bytes,model.label.replace(/\.gba$/i,'')+'_自定义.gba');notify('新 ROM 已导出；请在模拟器中验证所改关卡。');});
$('#exportIps').onclick=()=>run(()=>{const bytes=exportBytes();download(E.ips(model.rom,bytes),model.label.replace(/\.gba$/i,'')+'_自定义.ips');notify('IPS 已导出，只适用于当前打开的这份 ROM。');});
$('#saveProject').onclick=()=>run(()=>download(JSON.stringify(model.project(sha),null,2),`木叶工房_工程_${stage}.json`,'application/json'));
$('#projectFile').onchange=async e=>{const f=e.target.files[0];if(f)try{model.importProject(JSON.parse(await f.text()),sha);initializeFlow();render();updateStatus();notify('工程已载入');}catch(err){notify(err.message,true);}e.target.value='';};
$('#undo').onclick=()=>run(()=>{notify(`已撤销：${model.undo()}`);render();updateStatus();});
window.addEventListener('beforeunload',e=>{if(model&&(model.edits.size||model.textEdits.size||model.hasExtraChanges())){e.preventDefault();e.returnValue='';}});
